// One Telegram message per matching post, newest last, capped per run.
const posts = $input.all().map((i) => i.json).filter((p) => p.postId && p.url);
if (!posts.length) return [];
const cfg = $('Settings').first().json;
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (n) => (n == null ? '?' : Number(n).toLocaleString('en-US'));
const picked = posts.sort((a, b) => (a.date || '').localeCompare(b.date || '')).slice(-cfg.maxAlertsPerRun);
const out = picked.map((p) => {
  const snippet = p.text.length > 600 ? p.text.slice(0, 600) + '…' : p.text;
  return { json: { text: [
    `<b>${esc(p.channelTitle || p.channel)}</b> · ${esc((p.matchedKeywords || []).join(', '))}`,
    esc(snippet),
    `${fmt(p.views)} views · ${String(p.date).slice(0, 16).replace('T', ' ')} UTC`,
    p.url,
  ].join('\n\n') } };
});
if (posts.length > picked.length) out.push({ json: { text: `${posts.length - picked.length} more matching posts this run were not sent (limit ${cfg.maxAlertsPerRun}).` } });
return out;
